+    // Do things when first enabled or disabled
+    if (frc::DriverStation::IsDisabled() != true &&
+        frc::DriverStation::IsAutonomousEnabled() == false) {
+        if (!EnteredDisabled) {
+            EnteredDisabled = true;
+            EnteredEnabled = false;
