+    } else {
+        if (!EnteredEnabled) {
+            // we are enabled or in auto, so set brake mode
+            EnteredEnabled = true;
+            EnteredDisabled = false;
+            TeleopInit();
+        }
+    }
+}
+
+void DriveSubsystem::ArcadeDrive(double fwd, double rot) {
+    double currentPercentage = fwd;
+    if (abs(currentPercentage) >
