+            .map_err(|e| {
+                tracing::error!(%e, "could not read JWKS path");
+                e
+            })
+            .ok()?
+    } else {
+        let my_client = CLIENT
+            .as_ref()
+            .map_err(|e| {
+                tracing::error!(%e, "could not activate commercial features");
